"""README.md is generated by scripts/build_readme.py from README.template.md and committed result files.

python -m pytest tests/test_readme.py -q
(a) README.md equals a fresh build; (b) every digit comes from a generated span or matches the allow-list
scripts/build_readme.py ALLOWED; (c) every quotation occurs verbatim in its source; (d) every relative link
resolves to a file or folder in the repository; (e) every value also stated in a source table is equal there.
Also: the template holds no number, headings go no deeper than ###, plain wording, and the repository map lists
exactly the tracked top-level folders.
"""
from __future__ import annotations

import importlib.util
import re
import subprocess
from pathlib import Path

ROOT = Path(__file__).resolve().parents[1]
spec = importlib.util.spec_from_file_location("build_readme", ROOT / "scripts" / "build_readme.py")
br = importlib.util.module_from_spec(spec)
spec.loader.exec_module(br)
TEXT, SPANS, CHECKS = br.build()
README = (ROOT / "README.md").read_text(encoding="utf-8")


def outside_spans(text: str, spans: list[dict]) -> str:
    out, pos = [], 0
    for s in spans:
        out.append(text[pos:s["start"]])
        out.append(" ")
        pos = s["end"]
    return "".join(out + [text[pos:]])


def stray_digits(text: str) -> list[str]:
    for _, pattern in br.ALLOWED:
        text = re.sub(pattern, " ", text)
    return [l.strip() for l in text.splitlines() if re.search(r"\d", l)]


def test_a_readme_equals_fresh_build():
    assert README == TEXT, "README.md is stale: run python scripts/build_readme.py"


def test_b_digits_come_from_generated_spans_or_the_allow_list():
    assert stray_digits(outside_spans(TEXT, SPANS)) == []


def test_b_allow_list_does_not_hide_a_typed_number():
    assert stray_digits("Assistant 145 of 200 after SFT.") and not stray_digits("Qwen3-14B, F14, v1.2, ADR-037.")


def test_template_has_no_number():
    tpl = br.TEMPLATE.read_text(encoding="utf-8")
    assert stray_digits(br.PLACEHOLDER.sub(" ", tpl)) == []


def test_c_quotes_occur_verbatim_in_their_source():
    quotes = [s for s in SPANS if s["kind"] == "q"]
    assert len(quotes) >= 10
    for s in quotes:
        assert br.norm(TEXT[s["start"]:s["end"]]) in br.norm((ROOT / s["path"]).read_text(encoding="utf-8")), s


def test_d_relative_links_resolve():
    targets = re.findall(r"\]\(([^)\s]+)\)", TEXT) + re.findall(r'(?:src|srcset|href)="([^"]+)"', TEXT)
    rel = [t for t in targets if not re.match(r"[a-z]+:|#", t)]
    assert rel
    for t in rel:
        assert (ROOT / t.split("#")[0]).exists(), t
    anchors = {re.sub(r"[^\w\- ]", "", h.lower()).replace(" ", "-") for h in re.findall(r"(?m)^#+ (.+)$", TEXT)}
    for a in re.findall(r"\]\(#([^)]+)\)", TEXT):
        assert a in anchors, a


def test_e_values_equal_their_source_tables():
    files = {"results/method_table.md", "figures/T1.md", "results/redteam.md", "results/gguf_demo_models.md"}
    assert {f for _, f in CHECKS} & files == files
    for text, f in CHECKS:
        assert text in (ROOT / f).read_text(encoding="utf-8"), (text, f)


def test_style():
    assert "!" not in re.sub(r"<!--.*?-->|`[^`]*`|```.*?```|!\[|\]\(", "", TEXT, flags=re.S)
    assert not re.search(r"\b(?:novel|robust|state-of-the-art|cutting-edge|groundbreaking)\b", TEXT, re.I)
    assert not re.search(r"(?m)^#{4,} ", TEXT)
    assert "How this was built" not in TEXT


def test_repository_map_lists_the_tracked_folders():
    out = subprocess.run(["git", "-C", str(ROOT), "ls-files"], capture_output=True, text=True, check=True).stdout
    tracked = {p.split("/")[0] for p in out.splitlines() if "/" in p}
    mapped = set(re.findall(r"(?m)^\| `([\w-]+)/` \|", TEXT))
    assert mapped == tracked


def test_draft_removed_and_earlier_readme_linked_at_its_tag():
    assert not (ROOT / "README_v1.2_draft.md").exists() and not (ROOT / "docs" / "README_v1.1.1.md").exists()
    assert "/blob/v1.1.1/README.md" in TEXT


def test_local_demo_gives_both_shells():
    assert "CHINOR_MODELS_DIR=<folder" in TEXT and '$env:CHINOR_MODELS_DIR="<folder' in TEXT
